// AI Prompts: How can I configure Aspose.Cells to skip all comments during PDF conversion in C#? | Provide a code snippet that sets PrintComments to PrintNoComments for every sheet before exporting to PDF. | Explain the impact of the PrintComments setting on PDF output and related page‑setup options.

using System;
using Aspose.Cells;

// Shows how to omit worksheet comments from the PDF generated by Aspose.Cells for .NET. The sample adds a comment, configures PageSetup.PrintComments = PrintNoComments, and saves a clean PDF without comment markers.
class DisableCommentsPdfDemo
{
    static void Main()
    {
        // Create a new workbook and get the first worksheet
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];

        // Add a sample comment (optional, just to illustrate that comments exist)
        int commentIndex = sheet.Comments.Add("A1");
        Comment comment = sheet.Comments[commentIndex];
        comment.Note = "This comment will not be printed in the PDF.";

        // Disable printing of comments when converting to PDF
        sheet.PageSetup.PrintComments = PrintCommentsType.PrintNoComments;

        // Save the workbook as PDF; comments will be omitted from the output
        workbook.Save("output.pdf", SaveFormat.Pdf);
    }
}
